#!/usr/bin/env python3
# =====================================================================
#  apply_master_suite.py  —  fence MASTER_SUITE_20261122 (TD-079)
#
#  The master regression suite: every test suite in the repo in one weekly
#  run with a detailed report, a manifest that follows the tests, and a
#  weekly launchd job (Friday 16:00 IST). Test tooling only: no app code changes.
#
#   scripts/regression/master_suite.py     NEW  run | refresh | check | list  (report in ~/scalp-regression/)
#   scripts/regression/schedule.py         NEW  install | status | run-now | uninstall (launchd, Fri 16:00)
#   scripts/regression/MASTER_SUITE.md     NEW  generated: every suite, runner, hash, TC IDs
#   scripts/hooks/master_suite_refresh.py  NEW  pre-commit: a test added/changed/deleted -> manifest refreshed + staged
#   scripts/test_master_suite.py           NEW  TC-REGR-0001…0029
#   .pre-commit-config.yaml                EDIT +master-suite-refresh hook         (.bak-MASTER_SUITE_20261122)
#   scripts/gen_repo_map.py                EDIT REPO_MAP Tests line for the suite  (.bak-MASTER_SUITE_20261122)
#   scripts/test_precommit_hooks.py        EDIT TC-HOOKS-0026/0027 count 6 hooks   (.bak-MASTER_SUITE_20261122)
#   REPO_MAP.md                            regenerated                              (.bak-MASTER_SUITE_20261122)
#
#     cd ~/dev/scalp-app && python3 apply_master_suite.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then:  python3 scripts/regression/schedule.py install      (Friday 16:00; --day / --time to change)
#         python3 scripts/regression/master_suite.py run      (a run now, ~1 h)
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "MASTER_SUITE_20261122"
PARENTS = {"scripts/gen_repo_map.py": ["REPO_MAP_FIX_20261117"],
           ".pre-commit-config.yaml": ["RELIABILITY_GATE_20261118"],
           "scripts/test_precommit_hooks.py": ["PUSH_ANYTIME_20261118"]}
GENERATED = ["scripts/regression/MASTER_SUITE.md"]
ITEMS = json.loads(r"""[{"path": "scripts/regression/master_suite.py", "old": null, "new": "b23e3f1bcdbd4ec3a0718721f6c7d9de79c6e468f1839eb484a324a070196851", "blob": ""}, {"path": "scripts/regression/schedule.py", "old": null, "new": "c1082c5a277b55fe6fcc6414aa88d07eccdd9b37ef7cfab65905bb325ae3cda8", "blob": ""}, {"path": "scripts/hooks/master_suite_refresh.py", "old": null, "new": "539948ccd697e868d2c9cc82f557c58111ae62073e84d2ff6d4f0b338789e4be", "blob": ""}, {"path": "scripts/test_master_suite.py", "old": null, "new": "389c1c8150b4668973c01cdb791f581137dc1afbf4e09a9197eb602ffe3e9440", "blob": ""}, {"path": ".pre-commit-config.yaml", "old": "8cc67a247da56295d3d4f03bcc0378f1acc80f6f4ffe8e28211c7fbd67248b6a", "new": "34810660193fc952c6e3b3b898b3c920e58c8ccf80af97c56a300d54c5f62a36", "blob": ""}, {"path": "scripts/gen_repo_map.py", "old": "4d60bc97b1517ee42768f917a233fb99e8c267e2f2ede426ed598ca151a878aa", "new": "029bd123c21e82507eeb19a931c11b17ea3bbef2aa63e411ac20aa49ff6712a8", "blob": ""}, {"path": "scripts/test_precommit_hooks.py", "old": "f07e71a09edc58b61f6100e28e3d895285fad5b2e65a35cc536b7f79e98a5a1f", "new": "a0a793e46e95e82e9c76863775247d50a45ac6310651f642e8e8328baa15ca34", "blob": ""}]""")


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


def rd(p):
    if not os.path.exists(p):
        return None
    with open(p, "rb") as f:
        return f.read()


def wr(p, b):
    os.makedirs(os.path.dirname(p) or ".", exist_ok=True)
    t = p + ".tmp-" + FENCE
    with open(t, "wb") as f:
        f.write(b)
    os.replace(t, p)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
MAP = os.path.join(repo, "REPO_MAP.md")
GEN = os.path.join(repo, "scripts", "gen_repo_map.py")
TOOL = os.path.join(repo, "scripts", "regression", "master_suite.py")


def P(rel):
    return os.path.join(repo, rel)


def bak(rel):
    return P(rel) + ".bak-" + FENCE


def py(*a):
    r = subprocess.run([sys.executable, *a], cwd=repo, capture_output=True, text=True, timeout=1800)
    return r.returncode, (r.stdout + r.stderr).strip()


def git_dirty(rel):
    try:
        r = subprocess.run(["git", "-C", repo, "status", "--porcelain", "--", rel], capture_output=True,
                           text=True, timeout=30)
        return r.stdout.strip()
    except (OSError, subprocess.SubprocessError):
        return ""


def tidy():
    for d in ("scripts/regression/__pycache__", "scripts/hooks/__pycache__", "scripts/__pycache__"):
        d = P(d)
        if os.path.isdir(d):
            for n in os.listdir(d):
                if "master_suite" in n or n.startswith("schedule."):
                    os.remove(os.path.join(d, n))
            if not os.listdir(d):
                os.rmdir(d)
    d = P("scripts/regression")
    if os.path.isdir(d) and not os.listdir(d):
        os.rmdir(d)


# ── rollback ─────────────────────────────────────────────────────────
if "--rollback" in args:
    later = []
    for it in ITEMS:
        cur = rd(P(it["path"]))
        if cur is not None and sha(cur) != it["new"] and not (it["old"] and sha(cur) == it["old"]):
            later.append(it["path"])
    if later:
        die("cannot roll back — changed after this script: " + ", ".join(later) + ". Undo those edits first.")
    if os.path.exists(P("scripts/regression/schedule.py")) and sys.platform == "darwin":
        rc, msg = py(P("scripts/regression/schedule.py"), "uninstall")
        say("  weekly job: " + msg.splitlines()[-1] if msg else "  weekly job removed")
    for it in ITEMS:
        rel = it["path"]
        if it["old"] is None:
            if os.path.exists(P(rel)):
                os.remove(P(rel))
                say(f"  removed {rel}")
        elif os.path.exists(bak(rel)):
            shutil.copy2(bak(rel), P(rel))
            os.remove(bak(rel))
            say(f"  restored {rel}")
    for rel in GENERATED:
        if os.path.exists(P(rel)):
            os.remove(P(rel))
            say(f"  removed {rel}")
    if os.path.exists(GEN):
        ok, msg = py(GEN)
        say("  REPO_MAP.md regenerated" if ok == 0 else f"  !! generator: {msg}")
    if os.path.exists(MAP + ".bak-" + FENCE):
        os.remove(MAP + ".bak-" + FENCE)
    tidy()
    say("rolled back. Stage it: git add -A scripts .pre-commit-config.yaml REPO_MAP.md && git commit")
    sys.exit(0)

# ── 1. state ─────────────────────────────────────────────────────────
plan, done = [], 0
for it in ITEMS:
    cur = rd(P(it["path"]))
    if cur is not None and sha(cur) == it["new"]:
        done += 1
    elif it["old"] is None and cur is not None:
        die(f"{it['path']} already exists with other content — move it aside and re-run")
    elif it["old"] is not None and (cur is None or sha(cur) != it["old"]):
        die(f"{it['path']} is not the version this script was built on (main 0d6c9ced) — pull the latest main "
            "and ask for a rebuilt script")
    else:
        plan.append(it)
if not plan:
    say(f"✓ already applied ({done} file(s) in place) — refreshing the generated files only")
for rel, fences in PARENTS.items():
    cur = rd(P(rel)) or b""
    miss = [f for f in fences if f.encode() not in cur]
    if miss:
        die(f"{rel} lacks {', '.join(miss)} — pull the latest main first")
if plan and "--allow-dirty" not in args:
    for rel in ["REPO_MAP.md"] + [it["path"] for it in ITEMS if it["old"]]:
        st = git_dirty(rel)
        if st:
            die(f"git status shows {rel} as '{st[:2].strip()}' — commit or stash it first (or --allow-dirty)")

# ── 2. compile ───────────────────────────────────────────────────────
tmp = tempfile.mkdtemp(prefix="msuite_apply_")
for it in plan:
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        with open(f, "wb") as h:
            h.write(blobs[it["path"]])
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
shutil.rmtree(tmp, ignore_errors=True)
if plan:
    say(f"payloads verified and compiled ({len(plan)} file(s))")

# ── 3. write, all or nothing ─────────────────────────────────────────
written = []
old_map = rd(MAP)
try:
    for it in plan:
        rel = it["path"]
        if it["old"] is not None and not os.path.exists(bak(rel)):
            shutil.copy2(P(rel), bak(rel))
        wr(P(rel), blobs[rel])
        written.append(it)
        say(f"  {'new  ' if it['old'] is None else 'edit '} {rel}")
    if old_map is not None and not os.path.exists(MAP + ".bak-" + FENCE):
        wr(MAP + ".bak-" + FENCE, old_map)
    rc, msg = py(TOOL, "refresh")
    if rc != 0:
        raise RuntimeError("master_suite.py refresh: " + msg)
    say("  " + msg)
    rc, msg = py(GEN)
    if rc != 0:
        raise RuntimeError("gen_repo_map.py: " + msg)
    say("  REPO_MAP.md regenerated")
except Exception as e:                                   # put everything back
    for it in written:
        if it["old"] is None:
            os.remove(P(it["path"]))
        elif os.path.exists(bak(it["path"])):
            shutil.copy2(bak(it["path"]), P(it["path"]))
            os.remove(bak(it["path"]))
    for rel in GENERATED:
        if os.path.exists(P(rel)):
            os.remove(P(rel))
    if old_map is not None:
        wr(MAP, old_map)
    tidy()
    die(f"{e} — rolled back what was written")

# ── 4. tests ─────────────────────────────────────────────────────────
if "--skip-tests" not in args:
    bad = 0
    for t in ("scripts/test_master_suite.py", "scripts/test_precommit_hooks.py"):
        rc, out = py(P(t))
        last = out.splitlines()[-1] if out else ""
        say(f"  {'✓' if rc == 0 else '✗'} {t}: {last}")
        if rc != 0:
            bad += 1
            say("\n".join("      " + x for x in out.splitlines() if "FAIL" in x))
    if bad:
        say("\n!! tests failed — nothing was rolled back; see above (python3 apply_master_suite.py --rollback undoes it)")
        sys.exit(1)
tidy()
say(f"""
✓ {FENCE} applied.
  Weekly job (Friday 16:00):    python3 scripts/regression/schedule.py install
  A run now:                    python3 scripts/regression/master_suite.py run
  Report:                       ~/scalp-regression/latest/report.html
  Commit: git add scripts .pre-commit-config.yaml REPO_MAP.md && git commit
  (backups *.bak-{FENCE} stay out of the commit — the no-backup-files hook refuses them)""")
